 local lean=a.attack and (a.attack.t<a.attack.startup and 7 or -8) or (a.stun>0 and 12 or math.sin(a.walk)*1.3)
 art:SetLocalRotation(0,0,a.down>0 and -90*a.face or (a.launched and -35*a.face or lean*a.face))
